#!/usr/bin/env bash
# Formats de fichiers :
#   - envoi refusé pour tout format hors liste (images, vidéos, audio, PDF, texte, bureautique dont
#     doc/xls/ppt, zip, rar) ; extension et type déclaré doivent concorder ; jamais HTML, SVG, scripts ;
#   - documents des membres : seuls PDF, images, texte, audio, vidéo s'affichent, le reste se
#     télécharge ; en-têtes nosniff + sandbox ;
#   - doc à jour.
# Prérequis : apply-fix-documents-membres.sh.
# Usage (racine du repo) : bash apply-formats-autorises.sh
set -euo pipefail
cd "$(dirname "$0")"
[ -f pnpm-workspace.yaml ] || { echo "À lancer à la racine du repo."; exit 1; }

if git show HEAD:"packages/backend/src/modules/storage/router.ts" 2>/dev/null | grep -qF "uploadTypeError"; then echo "Déjà appliqué (commité)."; exit 0; fi
grep -qF "memberDocumentVisibleTo" "packages/backend/src/modules/memberDocuments/router.ts" 2>/dev/null || { echo "❌ lancer d'abord apply-fix-documents-membres.sh"; exit 1; }
MODIFIED=("apps/web/content/docs/dev/membres/documents-des-membres.mdx" "apps/web/content/docs/dev/stockage/envoyer-et-servir-un-fichier.mdx" "apps/web/src/app/api/media/member-document/[id]/route.ts" "packages/backend/src/modules/storage/router.ts")
CREATED=("packages/contracts/src/storage/allowedUploadTypes.ts")
restore(){ git checkout -q -- "${MODIFIED[@]}" 2>/dev/null || true; rm -f "${CREATED[@]}"; echo "  ↩ fichiers restaurés"; }
if grep -qF "uploadTypeError" "packages/backend/src/modules/storage/router.ts" 2>/dev/null; then echo "  restes d'un essai précédent non commité → nettoyage"; restore; fi
trap 'restore' ERR

