[ "${AKFC_APPLY_ONLY:-0}" = "1" ] && { echo "Appliqué (sans vérification ni commit)."; exit 0; }
echo "== pnpm check =="
if pgrep -f "next dev" >/dev/null 2>&1; then
  echo "  (pnpm dev tourne : vérification sans effacer .next)"
  CHECK="node scripts/check-next-conventions.mjs && node scripts/check-tour-targets.mjs && pnpm --filter backend typecheck && pnpm typecheck"
else
  CHECK="pnpm check"
fi
if ! bash -c "$CHECK" > /tmp/akfc_tc.log 2>&1; then
  echo "❌ check ÉCHOUÉ :"
  grep -nE "error TS|✗ tutos|ERR_|Error:|EACCES|Permission denied" /tmp/akfc_tc.log | head -12
  echo "  … fin du journal :"; grep -v '^[[:space:]]*$' /tmp/akfc_tc.log | tail -15
  restore; exit 1
fi
echo "  ✅ check OK"
git add "${MODIFIED[@]}" "${CREATED[@]}"
git commit -F - >/tmp/c.log 2>&1 <<'MSG' && echo "✅ commit $(git rev-parse --short HEAD)" || { echo "commit KO"; tail -3 /tmp/c.log; }
envois : formats autorisés seulement ; livraison des documents sans exécution possible

- contracts/storage/allowedUploadTypes.ts : liste des formats AUTORISÉS
  (images, vidéos, audio, PDF, texte, bureautique dont doc/xls/ppt, zip, rar),
  extension ET type déclaré concordants ; ni HTML, ni SVG, ni script.
- storage.createR2Upload refuse tout autre format (le type est signé dans
  l'URL d'envoi puis relu par registerR2Upload).
- /api/media/member-document : seuls PDF, images (hors SVG), texte, audio et
  vidéo s'affichent ; le reste en pièce jointe ; nosniff, et sandbox hors PDF.
- Doc : « Envoyer et servir un fichier », « Les documents des membres ».

